import { setCustomElementsManifest, type Preview } from '@storybook/web-components-vite';

import '../../examples/ui-kit/styles/index.css';
// Generated by scripts/custom-elements.mjs from stencilrs' own component metadata.
import manifest from '../generated/custom-elements.json';

// Register every component in both sets. Importing a component module (compiled by stencilrs
// through the Vite plugin) defines its custom element.
import.meta.glob(
  [
    '../../examples/ui-kit/src/**/*.tsx',
    '!../../examples/ui-kit/src/**/*.spec.tsx',
    '!../../examples/ui-kit/src/**/*.stories.tsx',
    '../../examples/starter/src/components/**/*.tsx',
  ],
  { eager: true },
);

setCustomElementsManifest(manifest);

// The ui-kit styles follow the OS colour scheme unless data-theme is set. Docs pages run no story
// decorator, so pin the light theme up front to match Storybook's light docs pages.
document.documentElement.setAttribute('data-theme', 'light');

const preview: Preview = {
  globalTypes: {
    theme: {
      description: 'Colour theme for the components',
      toolbar: { title: 'Theme', icon: 'circlehollow', items: ['light', 'dark'], dynamicTitle: true },
    },
  },
  initialGlobals: { theme: 'light' },
  decorators: [
    (story, context) => {
      document.documentElement.setAttribute('data-theme', context.globals.theme ?? 'light');
      return story();
    },
  ],
  parameters: {
    controls: { expanded: true },
    options: {
      storySort: {
        order: [
          'Docs',
          ['Introduction', 'Getting started', 'Writing components', 'Vite plugin', 'API', 'Testing', 'Migrating to Stencil v5', 'How it works', 'How it was built', 'Parity and verification', 'Benchmarks', 'Stencil quirks', 'Roadmap', 'Reference'],
          'UI Kit',
          'Starter',
        ],
      },
    },
  },
};

export default preview;
